import {REPORT_NAMES,fieldNames,inputType,MATERIALS,METERS,DEPARTMENTS,derived,summary,glueDays} from './report-model.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateIST=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const types=REPORT_NAMES.filter(t=>t!=='Employee Task');
let state=null,token=sessionStorage.getItem('starish-session')||'',tab='Overview',reportType='Boardline Production',page=0,search='',busy=false,timer,installPrompt,taskView='all',taskEmployee='',taskEmployeeSearch='',routineSelected=new Set(),routineEmployeeSearch='',routineAssignee='',routineDue='';
const admin=()=>state&&['Owner','Plant Head'].includes(state.user.role);
const badge=s=>`<span class="badge ${s==='Approved'||s==='Closed'?'approved':''}">${esc(s||'Not reviewed')}</span>`;
const overdue=t=>!['Submitted','Closed','Removed'].includes(t.status)&&Date.parse(t.due)<Date.now();
const employeeOptions=selected=>`<option value="">Select employee</option>`+(state.users||[]).filter(u=>u.active).map(u=>`<option value="${esc(u.email)}" ${u.email===selected?'selected':''}>${esc(u.name)} (${esc(u.loginEmail||u.phone||u.email)})</option>`).join('');
const option=(list,value)=>list.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function message(s){$('#message').textContent=s;$('#message').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#message').hidden=true,8000);}
function api(action,data={},mutation=false){const url=window.PORTAL_CONFIG?.apiUrl;
 if(!/^https:\/\/script\.google\.com\/macros\/s\/[a-zA-Z0-9_-]+\/exec$/.test(url||''))return Promise.reject(Error('Set the NEW portal Apps Script URL in config.js first.'));
 if(!navigator.onLine)return Promise.reject(Error('Internet is required to read or save data.'));
 const nonce=Array.from(crypto.getRandomValues(new Uint8Array(24)),v=>v.toString(16).padStart(2,'0')).join(''),requestId=crypto.randomUUID();
 return new Promise((resolve,reject)=>{const frame=document.createElement('iframe'),form=document.createElement('form'),input=document.createElement('input');frame.name='api_'+nonce;frame.hidden=true;form.hidden=true;form.method='POST';form.action=url;form.target=frame.name;input.type='hidden';input.name='payload';input.value=JSON.stringify({action,data,token,nonce,requestId,origin:location.origin});form.append(input);
 const timeout=setTimeout(()=>finish(Error(mutation?'Save confirmation timed out. Refresh and check the record before retrying.':'Connection timed out. Check deployment access and frontend origin.')),90000);
 function receive(e){let host;try{const u=new URL(e.origin);if(u.protocol!=='https:')return;host=u.hostname;}catch{return;}
 if(!(host==='script.google.com'||host==='script.googleusercontent.com'||host.endsWith('.googleusercontent.com')))return;
 if(e.data?.channel!=='starish-api'||e.data.nonce!==nonce)return;
 if(e.data.result?.ok)finish(null,e.data.result);else finish(Error(e.data.result?.error||'Request failed'));
 }
 function finish(error,result){clearTimeout(timeout);window.removeEventListener('message',receive);form.remove();frame.remove();error?reject(error):resolve(result);}
 window.addEventListener('message',receive);document.body.append(frame,form);form.submit();
 });
}
async function load(){if(busy)return;busy=true;$('#refresh').disabled=true;try{const r=await api('workspace',{from:$('#from').value,to:$('#to').value});state=r;$('#login').hidden=true;$('#shell').hidden=false;$('#logout').hidden=false;$('#identity').textContent=r.user.name+' · '+r.user.role;render();}catch(e){if(/Login expired|Account inactive/.test(e.message))signoutLocal();message(e.message);}finally{busy=false;$('#refresh').disabled=false;}}
function visibleTypes(){return admin()?types:types.filter(t=>state.user.forms.includes(t)||t==='Glue Consumption'&&state.user.forms.includes('Glue Kitchen Stock'));}
function filtered(){const shift=$('#shift').value,review=$('#review').value;return state.reports.filter(r=>(shift==='All'||r.shift===shift)&&(review==='All statuses'||(review==='Approved'?r.status==='Approved':r.status!=='Approved')));}
function render(){if(admin()&&tab==='Tasks')tab='Overview';const tabs=(admin()?['Overview','Reports','Notifications','My account','Employees','Daily routines','Sources']:['Overview','Reports','Tasks','Notifications','My account']);$('#nav').innerHTML=tabs.map(t=>`<button data-tab="${esc(t)}" class="${tab===t?'active':''}">${esc(t)}${t==='Notifications'?' ('+state.notifications.filter(n=>!n.read).length+')':''}</button>`).join('');$('#pageTitle').textContent=tab;$('#filters').hidden=!['Overview','Reports'].includes(tab);let html='';
 if(tab==='Overview'){const t=scopedTasks().filter(t=>t.status!=='Removed');html=`${admin()?'<div class="toolbar"><button data-new-task>+ Assign task</button></div>'+taskEmployeePicker():''}<div class="kpis">${[['Pending tasks',t.filter(t=>!['Submitted','Closed'].includes(t.status)).length,'pending'],['Completed tasks',t.filter(t=>['Submitted','Closed'].includes(t.status)).length,'completed'],['Assigned tasks',t.filter(t=>taskKind(t)==='assigned').length,'assigned'],['Overdue',t.filter(overdue).length,'overdue']].map(([label,n,view])=>`<button class="card" data-task-view="${view}"><small>${label}</small><strong>${n}</strong><small>Tap to view</small></button>`).join('')}${admin()?`<button class="card" data-task-view="removal"><small>Removal approval requests</small><strong>${t.filter(t=>t.removalRequest?.status==='Requested').length}</strong><small>Tap to review</small></button>`:''}</div>${!admin()||taskView!=='all'?employeeTaskOverview():''}<h2>Report summary · ${esc($('#from').value)} to ${esc($('#to').value)}</h2><div class="grid">${visibleTypes().map(type=>`<button class="summary-card" data-type="${esc(type)}"><small>${type.includes('Production')?'EXISTING SOURCE':type==='Glue Consumption'?'CALCULATED':'REPORT'}</small><h2>${esc(type)}</h2>${summary(type,filtered(),state.batchChangeover).slice(0,3).map(m=>`<div class="metric"><span>${esc(m.label)}</span><b>${esc(m.value)}</b></div>`).join('')}<span class="link">View details & inquiry →</span></button>`).join('')}</div>`;}
 if(tab==='Reports')html=reportsHtml();
 if(tab==='Tasks')html=tasksHtml();
 if(tab==='Notifications')html=`<div class="card">${state.notifications.map(n=>`<div class="history"><b>${esc(n.title)}</b><small>${esc(new Date(n.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small><div class="form-actions">${n.taskId?`<button data-task="${esc(n.taskId)}">View task</button>`:''}${n.reportId?`<button data-report="${esc(n.reportId)}">View report</button>`:''}${!n.read?`<button class="secondary" data-read="${esc(n.id)}">Mark read</button>`:'<small>Read</small>'}</div></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</div>`;
 if(tab==='My account')html=`<div class="card"><h2>Mobile + PIN login</h2><p>Registered email: ${esc(state.user.loginEmail||'Not set')}<br>Mobile: ${esc(state.user.phone||'Not set')}</p><p class="muted">Email OTP stays available if your account has an email. Register your mobile and set a private 6–12 digit PIN here. PIN changes sign out other existing sessions.</p><button id="changePin">Set / change my mobile PIN</button></div>`;
 if(tab==='Employees'){const employees=matchingEmployees(state.employees,search);html=`<div class="toolbar"><button data-new-employee>+ Add employee</button><input id="employeeSearch" type="search" placeholder="Search employee name / department / email / mobile" aria-label="Search employees" value="${esc(search)}"><small>${employees.length} of ${state.employees.length} employees</small></div><p class="muted">Add login email/mobile and form permissions. Owner account is configured separately.</p><div class="card table-wrap"><table><thead><tr><th>Name</th><th>Department</th><th>Email / mobile / access</th><th>Action</th></tr></thead><tbody>${employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(e.email||'Email not set')}<small>${esc(e.phone||'Mobile not set')}</small><small>${esc(e.role)} · ${e.active?'Active':'Inactive'} · ${esc((e.forms||[]).join(', '))}</small></td><td><button data-employee="${esc(e.id)}">Configure</button></td></tr>`).join('')}</tbody></table>${!employees.length?'<div class="empty">'+(state.employees.length?'No matching employee. Try another name or department.':'No employees added yet.')+'</div>':''}</div>`;}
 if(tab==='Daily routines')html=routinesHtml();
 if(tab==='Sources')html=`<div class="toolbar"><button data-new-source>+ Connect report Sheet</button><button class="secondary" id="sync">Sync enabled sources</button></div><p class="notice">Existing entry apps stay unchanged. Connect source Sheet tabs and exact column mappings. Loading source is preconfigured but disabled until you enable it. Stage report calculation remains in the existing PC workflow; this portal reads the resulting STAGE_TIME data.</p><div class="card table-wrap"><table><thead><tr><th>Source</th><th>Enabled</th><th>Last sync</th><th>Action</th></tr></thead><tbody>${state.sources.map(s=>{const st=state.syncStatus.find(x=>x.id===s.id);return `<tr><td>${esc(s.name)}<small>${esc(s.kind==='loading'?'Loading + Stage':s.type+' / '+s.tab)}</small></td><td>${s.enabled?'Yes':'No'}</td><td>${st?esc(st.lastSuccess||'No successful sync')+`<small>${st.rows||0} rows · ${esc(st.error||'OK')}</small>`:'Not synced'}</td><td><button data-source="${esc(s.id)}">Configure</button></td></tr>`;}).join('')}</tbody></table></div>`;
 $('#content').innerHTML=html;bindContent();}
function pagination(pages){return `<div class="pagination"><button class="secondary" data-page="-1" ${page===0?'disabled':''}>Previous</button><small>Page ${page+1} / ${pages}</small><button class="secondary" data-page="1" ${page>=pages-1?'disabled':''}>Next</button></div>`;}
function reportsHtml(){const available=visibleTypes();if(!available.includes(reportType))reportType=available[0]||'';const rows=filtered().filter(r=>r.type===reportType&&JSON.stringify(r.fields).toLowerCase().includes(search.toLowerCase())),pages=Math.max(1,Math.ceil(rows.length/30));page=Math.min(page,pages-1);
 let html=`<div class="toolbar"><select id="reportType">${option(available,reportType)}</select><button id="pdf" class="secondary">Download PDF</button>${reportType&&!reportType.includes('Production')&&!['Glue Consumption','Stage Report'].includes(reportType)?'<button id="newReport">+ New entry</button>':''}<input id="reportSearch" placeholder="Search details" value="${esc(search)}"></div><div class="kpis">${summary(reportType,filtered(),state.batchChangeover).slice(0,reportType==='Water Meter'?Infinity:4).map(m=>`<div class="card"><small>${esc(m.label)}</small><strong style="font-size:20px">${esc(m.value)}</strong></div>`).join('')}</div>`;
 if(reportType==='Glue Consumption'){return html+`<div class="card table-wrap"><table><thead><tr><th>Date</th><th>Starch kg</th><th>Batches</th><th>Boardline tonnes</th><th>Glue kg/ton</th></tr></thead><tbody>${glueDays(filtered(),state.batchChangeover).map(g=>`<tr><td>${g.date}</td><td>${g.starch.toFixed(2)}</td><td>${g.batches?.toFixed(2)||'Unavailable'}</td><td>${g.tonnes.toFixed(3)}</td><td>${g.consumption===null?'Missing production / shifts':g.consumption.toFixed(2)}</td></tr>`).join('')}</tbody></table><p class="muted">Both Boardline shifts required. Batch size: 200 kg before 10 Sep 2026, 150 kg from 10 Sep 2026. Entry-specific batch size takes precedence.</p></div>`;}
 return html+`<div class="card table-wrap"><table><thead><tr><th>Date / Shift</th><th>Report details</th><th>Review status</th><th>Action</th></tr></thead><tbody>${rows.slice(page*30,page*30+30).map(r=>`<tr><td>${esc(r.date)}<small>${esc(r.shift)}</small></td><td><b>${esc(r.fields['Machine / Process']||r.fields['Material Name']||r.fields['Meter Name']||r.fields['Customer Name']||r.fields.Customer||r.type)}</b><small>${esc(Object.entries(r.fields).filter(([,v])=>v!=='').slice(0,3).map(([k,v])=>k+': '+v).join(' · '))}</small></td><td>${badge(r.status)}</td><td><button data-report="${esc(r.id)}">Open details</button></td></tr>`).join('')}</tbody></table>${rows.length?pagination(pages):'<div class="empty">No records in this range. Connect source sheets or enter department reports.</div>'}</div>`;}
function bindContent(){bindRoutineBulk();if($('#taskEmployee'))$('#taskEmployee').onchange=e=>{taskEmployee=e.target.value;render();};if($('#taskEmployeeSearch'))$('#taskEmployeeSearch').oninput=e=>{const pos=e.target.selectionStart;taskEmployeeSearch=e.target.value;render();const el=$('#taskEmployeeSearch');el.focus();if(pos!==null)el.setSelectionRange(pos,pos);};document.querySelectorAll('[data-task-view]').forEach(b=>b.onclick=()=>{taskView=b.dataset.taskView;tab=admin()?'Overview':'Tasks';search='';render();});if($('#taskView'))$('#taskView').onchange=e=>{taskView=e.target.value;render();};document.querySelectorAll('[data-task-mode]').forEach(b=>b.onclick=()=>quickTaskAction(b.dataset.taskId,b.dataset.taskMode,b));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;page=0;search='';taskView='all';render();});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{reportType=b.dataset.type;tab='Reports';page=0;search='';render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page+=Number(b.dataset.page);render();});document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>openReport(b.dataset.report));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(state.tasks.find(t=>t.id===b.dataset.task)));document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{try{await api('markRead',{id:b.dataset.read});await load();}catch(e){message(e.message);}});
 for(const [selector,handler] of [['#reportType',e=>{reportType=e.target.value;page=0;search='';render();}],['#reportSearch',e=>searchChange(e,'reportSearch')],['#taskSearch',e=>searchChange(e,'taskSearch')],['#routineSearch',e=>searchChange(e,'routineSearch')],['#employeeSearch',e=>searchChange(e,'employeeSearch')]]){const el=$(selector);if(el)el[selector==='#reportType'?'onchange':'oninput']=handler;}
 if($('#changePin'))$('#changePin').onclick=ownPinForm;
 if($('#newReport'))$('#newReport').onclick=()=>entryForm();if($('#pdf'))$('#pdf').onclick=exportPdf;
 document.querySelectorAll('[data-new-task]').forEach(b=>b.onclick=()=>taskForm());document.querySelectorAll('[data-new-employee]').forEach(b=>b.onclick=()=>employeeForm());document.querySelectorAll('[data-employee]').forEach(b=>b.onclick=()=>employeeForm(state.employees.find(e=>e.id===b.dataset.employee)));document.querySelectorAll('[data-new-routine]').forEach(b=>b.onclick=()=>routineForm());document.querySelectorAll('[data-routine]').forEach(b=>b.onclick=()=>routineForm(state.routines.find(r=>r.id===b.dataset.routine)));document.querySelectorAll('[data-new-source]').forEach(b=>b.onclick=()=>sourceForm());document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceForm(state.sources.find(s=>s.id===b.dataset.source)));if($('#sync'))$('#sync').onclick=async()=>{try{const r=await mutate('sync');message(r.syncStatus.map(s=>s.error?s.error:s.rows+' rows synced').join('\n')||'No enabled sources');}catch(e){message(e.message);}};
}
function searchChange(e,id){const pos=e.target.selectionStart;search=e.target.value;page=0;render();const el=$('#'+id);el.focus();if(el.type!=='search'&&pos!==null)el.setSelectionRange(pos,pos);}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
async function mutate(action,data={}){const r=await api(action,data,true);$('#dialog').close();void load();return r;}
function submit(form,fn){form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]')||form.querySelector('button');b.disabled=true;try{await fn(new FormData(form));}catch(err){message(err.message);}finally{b.disabled=false;}};}
function inputField(k,value=''){let options=k==='Material Name'?MATERIALS:k==='Meter Name'?METERS:k==='Stock Unit'?['Bags','kg','litres','Nos']:k==='Container Type'?['Can','Barrel']:k==='Used For'?['DG','Forklift']:k==='Status'?['Pending','In progress','Completed']:null;const optional=['Breakdown Reason','Reason','Colour Changes','Starch per Bag (kg)','Starch per Batch (kg)'].includes(k);return `<label>${esc(k)}${options?`<select name="${esc(k)}">${option(options,value||options[0])}</select>`:`<input name="${esc(k)}" type="${inputType(k)}" ${inputType(k)==='number'?'min="0" step="any"':''} value="${esc(value)}" ${optional?'':'required'}>`}</label>`;}
function entryForm(r){const type=r?.type||reportType,fields=r?.fields||{},date=r?.date||dateIST();modal(r?'Correct '+type:'New '+type,`<form id="entryForm"><div class="form-grid"><label>Date<input name="date" type="date" value="${date}" required></label><label>Shift<select name="shift">${option(['Day','Night','Daily'],r?.shift||'Daily')}</select></label>${fieldNames(type).filter(k=>(type!=='DG Operation'||k!=='Diesel Consumption (litres)')&&(type!=='Diesel Consumption'||k!=='Issued Litres')).map(k=>inputField(k,fields[k]??(k==='Reading Multiplier'?'1':k==='Starch per Bag (kg)'?'50':k==='Starch per Batch (kg)'?(date<'2026-09-10'?'200':'150'):''))).join('')}${type==='Water Meter'?'<p id="waterOpeningNote" class="full notice">Opening reading will be fetched from the previous meter closing.</p>':''}${type==='Diesel Consumption'?'<p class="full notice">1 Can = 35 litres. 1 Barrel = 200 litres. Save a separate entry for each receiver/use; use the remaining stock as opening for the next entry. <strong id="dieselIssue"></strong></p>':''}${type==='DG Operation'?'<p class="full notice">Fixed diesel rate: 26 litres/hour. Enter duration as HH:MM (01:30 = 1 hour 30 minutes). <strong id="dgConsumption"></strong></p>':''}<label class="full">Remarks<textarea name="Remarks">${esc(fields.Remarks)}</textarea></label>${r?'<label class="full">Correction reason<textarea name="reason" required></textarea></label>':''}</div><div class="form-actions"><button type="submit">Save report</button></div></form>`);const f=$('#entryForm');if(type==='Water Meter'&&!r)setupWaterOpening(f);if(type==='Diesel Consumption'){const quantity=f.elements.namedItem('Container Quantity'),kind=f.elements.namedItem('Container Type');quantity.step='1';quantity.max='10000';const preview=()=>{$('#dieselIssue').textContent=quantity.value!==''?'Issued diesel: '+(Number(quantity.value)*(kind.value==='Can'?35:200))+' litres':'';};quantity.addEventListener('input',preview);kind.addEventListener('change',preview);preview();}if(type==='DG Operation'){const duration=f.elements.namedItem('Duration (HH:MM)');duration.placeholder='01:30';duration.pattern='[0-9]{1,2}:[0-5][0-9]';duration.inputMode='text';const preview=()=>{const match=duration.value.match(/^(\d{1,2}):([0-5]\d)$/);$('#dgConsumption').textContent=match?'Calculated diesel: '+((Number(match[1])*60+Number(match[2]))*26/60).toFixed(2)+' litres':'';};duration.addEventListener('input',preview);preview();}submit(f,async fd=>{const values={};fieldNames(type).concat('Remarks').forEach(k=>values[k]=fd.get(k));await mutate('saveReport',{id:r?.id,version:r?.version,type,date:fd.get('date'),shift:fd.get('shift'),fields:values,reason:fd.get('reason')});message('Report saved');});}
function setupWaterOpening(form){const meter=form.elements.namedItem('Meter Name'),date=form.elements.namedItem('date'),shift=form.elements.namedItem('shift'),opening=form.elements.namedItem('Opening Reading');let sequence=0,manual=false,autoValue='';opening.addEventListener('input',()=>{manual=true;});async function fetchOpening(){const request=++sequence,note=form.querySelector('#waterOpeningNote');if(!manual&&opening.value===autoValue)opening.value='';note.textContent='Looking up previous closing…';try{const result=await api('waterOpening',{meter:meter.value,date:date.value,shift:shift.value});if(request!==sequence||!form.isConnected)return;if(result.found){if(!manual){opening.value=result.reading;autoValue=result.reading;}note.textContent=(manual?'Previous closing (manual opening retained): ':'Opening fetched: ')+result.reading+' · '+result.date+' · '+result.shift+'. Verify before saving.';}else note.textContent=result.message||'No previous record for this meter. Enter opening manually.';}catch(err){if(request===sequence&&form.isConnected)note.textContent='Could not fetch opening: '+err.message+'. Enter verified opening manually.';}}[meter,date,shift].forEach(el=>el.addEventListener('change',fetchOpening));fetchOpening();}
async function openReport(id){try{const data=await api('reportDetail',{id}),r=data.report;modal(r.type+' · '+r.date,`<p>${esc(r.shift)} · ${badge(r.status)}</p>${r.source?`<p class="notice">Source: ${esc(r.source)}. Correct data in the existing source app or Sheet, then sync.</p>`:''}<dl class="details">${Object.entries({...r.fields,...derived(r)}).filter(([,v])=>v!=='').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="form-actions">${!r.source&&r.status!=='Approved'?'<button id="editReport" class="secondary">Correct entry</button>':''}${admin()?`<button id="approveReport">${r.status==='Approved'?'Reopen for correction':'Approve & lock'}</button><button id="followTask" class="secondary">Assign follow-up task</button>`:''}</div><h2>Inquiry / remark</h2><form id="remarkForm"><label>Remark<textarea name="text" required maxlength="3000"></textarea></label>${admin()?`<div class="form-grid"><label>Responsible employee<select name="assignee" required>${employeeOptions('')}</select></label><label>Deadline IST<input name="due" type="datetime-local"></label></div><label class="check"><input name="createTask" type="checkbox" checked>Create a follow-up task for this remark</label>`:''}<div class="form-actions"><button type="submit">Save remark</button></div></form><h2>Review and correction history</h2>${data.activity.map(e=>`<div class="history"><b>${esc(e.action)}</b><small>${esc(e.by)} · ${esc(e.at)}</small><p>${esc(e.reason||e.text||'')}</p>${e.before&&e.after?Object.entries(e.after).filter(([k,v])=>e.before[k]!==v).map(([k,v])=>`<small>${esc(k)}: ${esc(e.before[k])} → ${esc(v)}</small>`).join('<br>'):''}</div>`).join('')||'<p class="muted">No history yet.</p>'}`);
 if($('#editReport'))$('#editReport').onclick=()=>entryForm(r);if($('#followTask'))$('#followTask').onclick=()=>taskForm(null,r.id);if($('#approveReport'))$('#approveReport').onclick=async()=>{const mode=r.status==='Approved'?'reopen':'approve',reason=mode==='reopen'?prompt('Reason for reopening'):'';if(mode==='reopen'&&!reason)return;try{await mutate('reviewReport',{id:r.id,version:r.version,mode,reason});message(mode==='approve'?'Successfully Approved':'Report Reopened for Correction');}catch(e){message(e.message);}};
 const form=$('#remarkForm');if(form.elements.createTask)form.elements.createTask.onchange=()=>form.elements.due.required=form.elements.createTask.checked;if(form.elements.due)form.elements.due.required=true;
 submit(form,async fd=>{const due=fd.get('due');await mutate('remark',{id:r.id,text:fd.get('text'),assignee:fd.get('assignee'),createTask:fd.get('createTask')==='on',due:due?due+':00+05:30':''});message('Remark saved'+(fd.get('createTask')==='on'?' and task assigned':''));});
 }catch(e){message(e.message);}}
function taskForm(t,reportId=''){modal(t?'Edit task':'Assign / add task',`<form id="taskForm"><div class="form-grid"><label class="full">Task title<input name="title" maxlength="200" value="${esc(t?.title)}" required></label><label class="full">Instructions<textarea name="description">${esc(t?.description)}</textarea></label>${admin()?`<label>Employee<select name="assignee" required>${employeeOptions(t?.assignee)}</select></label>`:`<p>Assigned to: ${esc(state.user.name)}</p>`}<label>Deadline IST<input name="due" type="datetime-local" required value="${esc(t?.due?.slice(0,16))}"></label></div><div class="form-actions"><button type="submit">Save task</button></div></form>`);submit($('#taskForm'),async fd=>{await mutate('saveTask',{id:t?.id,version:t?.version,title:fd.get('title'),description:fd.get('description'),assignee:admin()?fd.get('assignee'):state.user.email,due:fd.get('due')+':00+05:30',reportId:t?.reportId||reportId});message('Task saved');});}
let taskOpenRequest=0;
async function openTask(t,draft='',notice=''){if(!t)return message('Task is not accessible.');const request=++taskOpenRequest;try{modal('Loading task…','<p class="notice">Fetching the latest task.</p>');const fresh=await api('taskDetail',{id:t.id});if(request!==taskOpenRequest)return;if(!state)state={user:fresh.user,tasks:[],notifications:[],reports:[]};const index=state.tasks.findIndex(task=>task.id===t.id);if(index<0)state.tasks.push(fresh.task);else state.tasks[index]=fresh.task;t=fresh.task;if(!t)return message('Task is no longer accessible.');renderTaskDialog(t,draft,notice);}catch(error){message(error.message);}}
function renderTaskDialog(t,draft='',notice=''){const owner=admin();modal(t.title,`${notice?'<p class="notice">'+esc(notice)+'</p>':''}<p>${badge(t.status)} ${overdue(t)?'<span class="badge overdue">Overdue</span>':''}</p><p>${esc(t.description)}</p><p>Assigned: ${esc(t.assignee)}<br>Deadline IST: ${esc(t.due)}</p>${t.workUpdate?'<div class="history"><b>Employee work update</b><p>'+esc(t.workUpdate)+'</p></div>':''}${t.reviewRemark?'<div class="history"><b>Review remark</b><p>'+esc(t.reviewRemark)+'</p></div>':''}${t.pendingReason?'<div class="history"><b>Pending reason</b><p>'+esc(t.pendingReason)+'</p></div>':''}${t.removalRequest?'<div class="history"><b>Removal request: '+esc(t.removalRequest.status)+'</b><p>'+esc(t.removalRequest.reason)+'</p><p>'+esc(t.removalRequest.remark||'')+'</p></div>':''}<form id="taskAction"><label>Work update / review remark<textarea name="text">${esc(draft)}</textarea></label><div class="form-actions"><button type="button" id="reloadTask" class="secondary">Reload latest task</button>${['Pending','In progress'].includes(t.status)?'<button type="submit" name="mode" value="submit">✓ Completed</button><button type="submit" name="mode" value="pending" class="secondary">Pending — reason required</button>':''}${!owner&&!['Closed','Removed'].includes(t.status)&&t.removalRequest?.status!=='Requested'?'<button type="submit" name="mode" value="requestRemoval" class="secondary">Request task removal</button>':''}${owner&&t.removalRequest?.status==='Requested'?'<button type="submit" name="mode" value="approveRemoval" class="danger">Approve removal</button><button type="submit" name="mode" value="rejectRemoval" class="secondary">Reject removal</button>':''}${owner&&t.status==='Submitted'?'<button type="submit" name="mode" value="close">Approve & close</button>':''}${owner&&['Submitted','Closed'].includes(t.status)?'<button type="submit" name="mode" value="return" class="danger">Return for correction</button>':''}${owner&&['Pending','In progress'].includes(t.status)?'<button type="button" id="editTask" class="secondary">Edit assignment / deadline</button>':''}</div></form>`);$('#taskAction').onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(!button)return;const form=e.target,text=String(new FormData(form).get('text')||'').trim();if(['return','submit','pending','requestRemoval','approveRemoval','rejectRemoval'].includes(button.value)&&!text){message(button.value==='return'?'Write the correction remark before returning the task.':'Write the work update, pending reason or removal decision remark.');form.elements.text.focus();return;}const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await mutate('taskAction',{id:t.id,version:t.version,mode:button.value,text});message(button.value==='return'?'Successfully Returned':button.value==='close'?'Successfully Approved':button.value==='submit'?'Completed — awaiting review':button.value==='requestRemoval'?'Removal request sent for approval':button.value==='approveRemoval'?'Task removal approved':button.value==='rejectRemoval'?'Task removal rejected':'Task updated');}catch(err){if(/Record changed/.test(err.message)){await openTask(t,text,'This task changed while you were reviewing. Latest data is loaded and your draft remark is preserved. Review the update and choose the action again.');}else message(err.message);}finally{buttons.forEach(b=>b.disabled=false);}};$('#reloadTask').onclick=()=>openTask(t,String(new FormData($('#taskAction')).get('text')||''));if($('#editTask'))$('#editTask').onclick=()=>taskForm(t);}
function employeeForm(e){const dept=e?.department||'Security',forms=e?.forms||DEPARTMENTS[dept]||[];modal(e?'Configure employee':'Add employee',`<form id="employeeForm"><div class="form-grid"><label>Name<input name="name" value="${esc(e?.name)}" required></label><label>Department<input name="department" list="departments" value="${esc(dept)}" required><datalist id="departments">${Object.keys(DEPARTMENTS).map(d=>`<option value="${esc(d)}">`).join('')}</datalist></label><label>Login email<input name="email" type="email" value="${esc(e?.email)}"><small>Blank email is allowed for mobile + PIN login. No email/phone = draft.</small></label><label>Mobile number<input name="phone" type="tel" value="${esc(e?.phone)}" placeholder="10 digits or +91…"></label><label>Set / reset PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6,12}" autocomplete="new-password"><small>6–12 digits. Leave blank to keep existing PIN.</small></label><label>Role<select name="role">${option(['Employee','Plant Head'],e?.role||'Employee')}</select></label><label class="check"><input type="checkbox" name="active" ${e?.active===false?'':'checked'}>Active</label></div><h2>Allowed report forms / history</h2><div class="form-grid">${types.filter(t=>t!=='Glue Consumption').map(t=>`<label class="check"><input type="checkbox" name="forms" value="${esc(t)}" ${forms.includes(t)?'checked':''}>${esc(t)}</label>`).join('')}</div><p class="muted">Production forms use existing source apps. These permissions allow viewing their saved reports. All employees see only their own tasks.</p><div class="form-actions"><button type="submit">Save employee</button></div></form>`);submit($('#employeeForm'),async fd=>{await mutate('saveEmployee',{id:e?.id,version:e?.version,name:fd.get('name'),department:fd.get('department'),email:fd.get('email'),phone:fd.get('phone'),pin:fd.get('pin'),role:fd.get('role'),active:fd.get('active')==='on',forms:fd.getAll('forms')});message('Employee saved');});}
function routineForm(r){modal('Daily task allocation',`<form id="routineForm"><label>Responsibility<input name="title" value="${esc(r?.title)}" required></label><div class="form-grid"><label>Employee<select name="assignee">${employeeOptions(r?.assignee)}</select></label><label>Frequency<select name="frequency">${option(['Daily','Weekly','Monthly','As needed'],r?.frequency||'Daily')}</select></label><label>Daily deadline IST<input name="dueTime" type="time" value="${esc(r?.dueTime)}"></label><label class="check"><input name="enabled" type="checkbox" ${r?.enabled?'checked':''}>Enable daily generation</label></div><p class="muted">Only Daily routines auto-generate. Original source label: ${esc(r?.sourceOwner||'Manual')}.</p><div class="form-actions"><button type="submit">Save allocation</button></div></form>`);submit($('#routineForm'),async fd=>{await mutate('saveRoutine',{id:r?.id,version:r?.version,title:fd.get('title'),assignee:fd.get('assignee'),frequency:fd.get('frequency'),dueTime:fd.get('dueTime'),enabled:fd.get('enabled')==='on'});message('Allocation saved');});}
function sourceForm(s){const loading=s?.kind==='loading';modal('Source report connector',`<form id="sourceForm"><label>Source name<input name="name" value="${esc(s?.name)}" required></label><label class="check"><input name="enabled" type="checkbox" ${s?.enabled?'checked':''}>Enable scheduled read-only sync</label>${loading?'<p>The existing Loading connector reads LOADING_ITEMS and STAGE_TIME. Existing entry app remains unchanged.</p>':`<div class="form-grid"><label>Source Spreadsheet ID<input name="spreadsheetId" value="${esc(s?.spreadsheetId)}" required></label><label>Tab name<input name="tab" value="${esc(s?.tab)}" required></label><label>Report type<select name="type">${option(types.filter(t=>t!=='Glue Consumption'),s?.type||'Boardline Production')}</select></label><label>Date column header<input name="dateColumn" value="${esc(s?.dateColumn||'Date')}" required></label><label>Shift column header (optional)<input name="shiftColumn" value="${esc(s?.shiftColumn)}"></label><label>Default shift<select name="defaultShift">${option(['Day','Night','Daily'],s?.defaultShift||'Daily')}</select></label><label class="full">Stable key columns, comma separated<input name="keyColumns" value="${esc((s?.keyColumns||[]).join(', '))}" required placeholder="Record ID"><small>Unique, unchanging keys are required to preserve correction history. Do not use row numbers.</small></label><label>Filter column (optional)<input name="filterColumn" value="${esc(s?.filterColumn)}" placeholder="MACHINE_NAME"></label><label>Allowed values, comma separated<input name="filterValues" value="${esc((s?.filterValues||[]).join(', '))}" placeholder="JF MACHINE, SMARTECH, NEW MACHINE"></label><p class="full">Only matching machines are imported. Leave both filter fields empty to import all rows. Matching ignores letter case and surrounding spaces.</p><label class="full">Field mapping JSON: portal field → source column<textarea name="mapping" rows="7" required>${esc(JSON.stringify(s?.mapping||{'Tonnage (kg)':'Tonnage (kg)','Metres':'Metres','Start Time':'Start Time','End Time':'End Time'},null,2))}</textarea></label></div>`}<div class="form-actions"><button type="submit">Save source</button></div></form>`);submit($('#sourceForm'),async fd=>{let mapping={};if(!loading)try{mapping=JSON.parse(fd.get('mapping'));}catch{throw Error('Field mapping must be valid JSON');}await mutate('saveSource',{id:s?.id,version:s?.version,name:fd.get('name'),enabled:fd.get('enabled')==='on',spreadsheetId:fd.get('spreadsheetId'),tab:fd.get('tab'),type:fd.get('type'),dateColumn:fd.get('dateColumn'),shiftColumn:fd.get('shiftColumn'),defaultShift:fd.get('defaultShift'),filterColumn:fd.get('filterColumn'),filterValues:String(fd.get('filterValues')||'').split(',').map(v=>v.trim()).filter(Boolean),keyColumns:String(fd.get('keyColumns')||'').split(',').map(s=>s.trim()).filter(Boolean),mapping});message('Source saved. Sync it to verify mappings.');});}
async function exportPdf(){const b=$('#pdf');b.disabled=true;try{const snapshot=await api('exportReports',{from:$('#from').value,to:$('#to').value,type:reportType,shift:$('#shift').value,review:$('#review').value});const reportIds=snapshot.reports,events=snapshot.activity;if(!reportIds.length)throw Error('No report records in this range.');message('Preparing PDF…');const [regular,bold]=await Promise.all(['report-font.ttf','report-font-bold.ttf'].map(f=>fetch('./'+f).then(r=>{if(!r.ok)throw Error('PDF font unavailable');return r.arrayBuffer();})));await ensurePdf();const {createReportPdf}=await import('./report-pdf.js');const bytes=await createReportPdf({type:reportType,from:$('#from').value,to:$('#to').value,approved:$('#review').value==='Approved',reports:reportIds,activity:events,generated:new Date().toISOString(),shift:$('#shift').value,machine:'',history:true,batchChangeover:state.batchChangeover},new Uint8Array(regular),new Uint8Array(bold));const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`Starish_${reportType.replace(/\s/g,'_')}_${$('#from').value}_${$('#to').value}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('PDF downloaded');}catch(e){message(e.message);}finally{b.disabled=false;}}
function signoutLocal(){token='';sessionStorage.removeItem('starish-session');state=null;$('#shell').hidden=true;$('#login').hidden=false;$('#logout').hidden=true;$('#identity').textContent='';}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api('loginRequest',{email:$('#email').value});$('#verifyForm').hidden=false;message(r.message);}catch(err){message(err.message);}finally{b.disabled=false;}};
$('#verifyForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api('loginVerify',{email:$('#email').value,code:$('#code').value});token=r.token;sessionStorage.setItem('starish-session',token);$('#code').value='';await load();}catch(err){message(err.message);}finally{b.disabled=false;}};
$('#logout').onclick=async()=>{try{await api('logout');}catch{}signoutLocal();};$('#closeDialog').onclick=()=>$('#dialog').close();$('#refresh').onclick=load;$('#apply').onclick=()=>{page=0;load();};$('#shift').onchange=()=>{page=0;if(state)render();};$('#review').onchange=()=>{page=0;if(state)render();};$('#from').value=$('#to').value=dateIST();
if(!window.PORTAL_CONFIG?.apiUrl){$('#setupMessage').hidden=false;$('#setupMessage').textContent='Setup pending: paste your new Apps Script portal backend /exec URL in config.js. See SETUP-HINDI guide.';}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(token)load();setInterval(()=>{if(token&&!$('#dialog').open&&!document.hidden)load();},60000);

function ownPinForm(){modal('Set / change my mobile PIN',`<form id="ownPinForm"><label>Mobile number<input name="phone" type="tel" value="${esc(state.user.phone)}" required></label><label>New PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6,12}" autocomplete="new-password" required></label><label>Confirm PIN<input name="confirm" type="password" inputmode="numeric" required></label><div class="form-actions"><button type="submit">Save my PIN</button></div></form>`);submit($('#ownPinForm'),async fd=>{if(fd.get('pin')!==fd.get('confirm'))throw Error('PINs do not match');await mutate('changeOwnPin',{phone:fd.get('phone'),pin:fd.get('pin')});message('PIN updated. You can now use mobile + PIN.');});}
async function ensurePdf(){for(const [src,key] of [['pdf-lib.min.js','PDFLib'],['fontkit.umd.min.js','fontkit']]){if(globalThis[key])continue;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='./'+src;script.onload=resolve;script.onerror=()=>reject(Error('Upload missing PDF file: '+src));document.head.append(script);});}}
$('#pinForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await api('loginPin',{phone:$('#phone').value,pin:$('#pin').value});token=r.token;sessionStorage.setItem('starish-session',token);$('#pin').value='';await load();}catch(error){message(error.message);}finally{button.disabled=false;}};
$('#emailMode').onclick=()=>{ $('#emailPanel').hidden=false;$('#pinPanel').hidden=true;$('#emailMode').classList.remove('secondary');$('#pinMode').classList.add('secondary');};
$('#pinMode').onclick=()=>{ $('#emailPanel').hidden=true;$('#pinPanel').hidden=false;$('#pinMode').classList.remove('secondary');$('#emailMode').classList.add('secondary');};

function matchingEmployees(employees,query){const words=String(query||'').trim().toLowerCase().split(/\s+/).filter(Boolean);return employees.filter(e=>{const text=[e.name,e.department,e.email,e.phone].filter(Boolean).join(' ').toLowerCase();return words.every(word=>text.includes(word));});}

function taskKind(t){return t.routineId||t.createdBy==='scheduler'?'daily':t.createdBy===t.assignee?'additional':'assigned';}
function tasksHtml(){const views=['all','pending','completed','assigned','daily','additional','overdue'].concat(admin()?['removal','removed']:[]),labels={all:'All tasks',pending:'Pending tasks',completed:'Completed tasks',assigned:'Assigned tasks',daily:'Daily tasks',additional:'My additional tasks',overdue:'Overdue tasks',removal:'Removal approval requests',removed:'Removed tasks (history)'};const tasks=scopedTasks().filter(t=>taskView==='removed'?t.status==='Removed':t.status!=='Removed').filter(t=>taskView==='pending'?!['Submitted','Closed'].includes(t.status):taskView==='completed'?['Submitted','Closed'].includes(t.status):taskView==='overdue'?overdue(t):taskView==='removal'?t.removalRequest?.status==='Requested':['assigned','daily','additional'].includes(taskView)?taskKind(t)===taskView:true).filter(t=>JSON.stringify(t).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.due.localeCompare(b.due));return `${admin()?taskEmployeePicker():''}<div class="toolbar"><button data-new-task>+ ${admin()?'Assign task':'Add my additional task'}</button><select id="taskView">${views.map(v=>`<option value="${v}" ${taskView===v?'selected':''}>${labels[v]}</option>`).join('')}</select><input id="taskSearch" placeholder="Search tasks" value="${esc(search)}"><small>Completed work awaits management review. Removal needs approval.</small></div>${['daily','assigned','additional'].map(kind=>{const list=tasks.filter(t=>taskKind(t)===kind);if(!list.length)return '';return `<h2>${kind==='daily'?'Daily task list':kind==='assigned'?'Assigned tasks':'Additional tasks'}</h2><div class="card table-wrap"><table><thead><tr><th>Task / reason</th><th>Employee</th><th>Deadline IST</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(t=>`<tr><td><b>${esc(t.title)}</b><small>${esc(t.description)}</small>${t.pendingReason?'<small>Pending: '+esc(t.pendingReason)+'</small>':''}${t.removalRequest?'<small>Removal '+esc(t.removalRequest.status)+': '+esc(t.removalRequest.reason)+'</small>':''}${t.reviewRemark?'<small>Review: '+esc(t.reviewRemark)+'</small>':''}</td><td>${esc((state.users||[]).find(u=>u.email===t.assignee)?.name||t.assignee)}</td><td>${esc(new Date(t.due).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</td><td>${overdue(t)?'<span class="badge overdue">OVERDUE</span> ':''}${['Submitted','Closed'].includes(t.status)?'<span class="badge approved">✓ Completed'+(t.status==='Submitted'?' · Awaiting review':' · Approved')+'</span>':badge(t.status)}</td><td><button data-task="${esc(t.id)}">Open</button>${t.assignee===state.user.email&&['Pending','In progress'].includes(t.status)?`<button data-task-id="${esc(t.id)}" data-task-mode="submit">Completed</button><button class="secondary" data-task-id="${esc(t.id)}" data-task-mode="pending">Pending</button>`:''}${t.assignee===state.user.email&&!['Closed','Removed'].includes(t.status)&&t.removalRequest?.status!=='Requested'?`<button class="secondary" data-task-id="${esc(t.id)}" data-task-mode="requestRemoval">Request removal</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}).join('')}${!tasks.length?'<div class="card empty">No tasks in this view. Daily routines must be enabled and assigned by management.</div>':''}`;}
async function quickTaskAction(id,mode,button){const t=state.tasks.find(t=>t.id===id);if(!t)return;const text=prompt(mode==='submit'?'Completed work update:':mode==='pending'?'Why is this task pending?':'Why should this task be removed?');if(text===null)return;if(!text.trim())return message('Reason / work update is required.');button.disabled=true;try{await mutate('taskAction',{id:t.id,version:t.version,mode,text:text.trim()});message(mode==='submit'?'Completed — awaiting review':mode==='pending'?'Pending reason saved':'Removal request sent for approval');}catch(e){message(e.message);if(/Record changed/.test(e.message))await load();}finally{button.disabled=false;}}

function scopedTasks(){return state.tasks.filter(t=>!admin()||!taskEmployee||t.assignee===taskEmployee);}
function taskEmployeeChoices(){const choices=new Map((state.users||[]).map(u=>[u.email,{id:u.email,name:u.name||u.email}]));state.tasks.forEach(t=>{if(!choices.has(t.assignee))choices.set(t.assignee,{id:t.assignee,name:t.assignee});});return [...choices.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function taskEmployeePicker(){const choices=taskEmployeeChoices().filter(u=>u.id===taskEmployee||u.name.toLowerCase().includes(taskEmployeeSearch.toLowerCase()));return `<div class="card"><h2>Employee task overview</h2><div class="toolbar"><label>Search employee name<input id="taskEmployeeSearch" type="text" value="${esc(taskEmployeeSearch)}" placeholder="Type employee name"></label><label>Employee<select id="taskEmployee"><option value="">All employees</option>${choices.map(u=>`<option value="${esc(u.id)}" ${u.id===taskEmployee?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div><small>Task counts and tap views use the selected employee. Report date filters apply to reports.</small></div>`;}
function employeeTaskOverview(){const tasks=scopedTasks().filter(t=>t.status!=='Removed').filter(t=>taskView==='pending'?!['Submitted','Closed'].includes(t.status):taskView==='completed'?['Submitted','Closed'].includes(t.status):taskView==='assigned'?taskKind(t)==='assigned':taskView==='overdue'?overdue(t):taskView==='removal'?t.removalRequest?.status==='Requested':true),ids=taskEmployee?[taskEmployee]:[...new Set(tasks.map(t=>t.assignee))],names=new Map(taskEmployeeChoices().map(u=>[u.id,u.name]));names.set(state.user.email,state.user.name);function section(title,list){return `<div class="card table-wrap"><h3>${title}</h3><table><thead><tr><th>Task</th><th>Status</th></tr></thead><tbody>${list.map(t=>`<tr><td><button class="secondary" data-task="${esc(t.id)}">${esc(t.title)}</button><small>Deadline: ${esc(new Date(t.due).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small>${t.pendingReason?'<small>Reason: '+esc(t.pendingReason)+'</small>':''}${t.removalRequest?.status==='Requested'?'<small>Removal approval requested</small>':''}</td><td>${['Submitted','Closed'].includes(t.status)?'<span class="badge approved">✓ Completed</span><small>'+(t.status==='Submitted'?'Awaiting review':'Approved')+'</small>':'<span class="badge">Pending</span>'}${overdue(t)?'<small class="badge overdue">Overdue</small>':''}</td></tr>`).join('')||'<tr><td colspan="2">No tasks</td></tr>'}</tbody></table></div>`;}return `<div class="toolbar"><h2>Employee tasks · ${esc(taskView==='all'?'All':taskView)}</h2><button class="secondary" data-task-view="all">${admin()?'Close task view':'Show all tasks'}</button></div>${ids.map(id=>{const own=tasks.filter(t=>t.assignee===id),daily=own.filter(t=>taskKind(t)==='daily'),assigned=own.filter(t=>taskKind(t)==='assigned'),extra=own.filter(t=>taskKind(t)==='additional');return `<section><h2>${esc(names.get(id)||id)}</h2><div class="grid">${section('Daily tasks',daily)}${section('Assigned tasks',assigned)}${extra.length?section('Additional tasks',extra):''}</div></section>`;}).join('')||'<div class="card empty">No tasks assigned yet. Assign and enable Daily routines to generate daily tasks.</div>'}`;}

function routinesHtml(){const routines=state.routines.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())),pages=Math.max(1,Math.ceil(routines.length/30));page=Math.min(page,pages-1);const shown=routines.slice(page*30,page*30+30),users=(state.users||[]).filter(u=>u.active&&(u.email===routineAssignee||u.name.toLowerCase().includes(routineEmployeeSearch.toLowerCase())));return `<div class="toolbar"><button data-new-routine>+ Add routine</button><input id="routineSearch" value="${esc(search)}" placeholder="Search person / task"><span>${routines.length} allocations</span></div><div class="card"><h2>Assign selected tasks to employee</h2><div class="toolbar"><label>Search employee<input id="routineEmployeeSearch" value="${esc(routineEmployeeSearch)}" placeholder="Employee name"></label><label>Assign to employee<select id="routineAssignee"><option value="">Select employee</option>${users.map(u=>`<option value="${esc(u.email)}" ${u.email===routineAssignee?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>Daily deadline IST<input id="routineDue" type="time" value="${esc(routineDue)}"></label><button id="assignSelectedRoutines">Assign selected (${routineSelected.size})</button><button id="selectMatchingRoutines" class="secondary">Select all ${routines.length} matching</button><button id="clearSelectedRoutines" class="secondary">Clear selection</button></div></div><p class="notice">Daily tasks will be enabled with the selected deadline. Weekly/monthly routines stay disabled for automatic generation. Remove employee stops future daily tasks and removes pending instances; completed history stays saved.</p><div class="card table-wrap"><table><thead><tr><th><input id="selectRoutinePage" type="checkbox" aria-label="Select current page" ${shown.length&&shown.every(r=>routineSelected.has(r.id))?'checked':''}></th><th>Responsibility</th><th>Employee</th><th>Schedule</th><th>Action</th></tr></thead><tbody>${shown.map(r=>`<tr><td><input type="checkbox" data-select-routine="${esc(r.id)}" aria-label="Select ${esc(r.title)}" ${routineSelected.has(r.id)?'checked':''}></td><td>${esc(r.title)}<small>Source: ${esc(r.sourceOwner||'Manual')}</small></td><td>${esc((state.users||[]).find(u=>u.email===r.assignee)?.name||r.assignee||'Not mapped')}</td><td>${esc(r.frequency)} ${esc(r.dueTime)}<small>${r.enabled?'Enabled':'Draft / disabled'}</small></td><td><button data-routine="${esc(r.id)}">Configure</button>${r.assignee?`<button class="danger" data-remove-routine="${esc(r.id)}">Remove employee</button>`:''}</td></tr>`).join('')}</tbody></table>${pagination(pages)}</div>`;}
function bindRoutineBulk(){if(tab!=='Daily routines')return;const matching=()=>state.routines.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));document.querySelectorAll('[data-select-routine]').forEach(b=>b.onchange=()=>{b.checked?routineSelected.add(b.dataset.selectRoutine):routineSelected.delete(b.dataset.selectRoutine);render();});$('#selectRoutinePage').onchange=e=>{matching().slice(page*30,page*30+30).forEach(r=>e.target.checked?routineSelected.add(r.id):routineSelected.delete(r.id));render();};$('#selectMatchingRoutines').onclick=()=>{matching().forEach(r=>routineSelected.add(r.id));render();};$('#clearSelectedRoutines').onclick=()=>{routineSelected.clear();render();};$('#routineEmployeeSearch').oninput=e=>{routineEmployeeSearch=e.target.value;const pos=e.target.selectionStart;render();const field=$('#routineEmployeeSearch');field.focus();if(pos!==null)field.setSelectionRange(pos,pos);};$('#routineAssignee').onchange=e=>routineAssignee=e.target.value;$('#routineDue').onchange=e=>routineDue=e.target.value;$('#assignSelectedRoutines').onclick=async e=>{if(!routineSelected.size||!routineAssignee||!routineDue)return message('Select tasks, employee and daily deadline.');e.target.disabled=true;try{const result=await mutate('bulkAssignRoutines',{items:state.routines.filter(r=>routineSelected.has(r.id)).map(r=>({id:r.id,version:r.version})),assignee:routineAssignee,dueTime:routineDue});routineSelected.clear();render();message(result.assigned+' routines assigned; '+result.daily+' daily routines enabled.');}catch(error){message(error.message);}finally{e.target.disabled=false;}};document.querySelectorAll('[data-remove-routine]').forEach(b=>b.onclick=async()=>{const r=state.routines.find(r=>r.id===b.dataset.removeRoutine),reason=prompt('Remove employee from this routine and its pending tasks. Reason:');if(reason===null)return;if(!reason.trim())return message('Removal reason required.');b.disabled=true;try{await mutate('removeRoutineEmployee',{id:r.id,version:r.version,reason:reason.trim()});message('Employee removed from routine. Completed history retained.');}catch(error){message(error.message);}finally{b.disabled=false;}});}
